CREATE TABLE IF NOT EXISTS public.flashcard_reviews (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), flashcard_id UUID NOT NULL REFERENCES public.flashcards(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, rating TEXT NOT NULL CHECK(rating IN ('again','hard','good','easy')), was_correct BOOLEAN, previous_interval INTEGER NOT NULL, next_interval INTEGER NOT NULL, reviewed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.vocabulary_test_attempts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, format TEXT NOT NULL, score NUMERIC(3,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.vocabulary_test_answers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id UUID NOT NULL REFERENCES public.vocabulary_test_attempts(id) ON DELETE CASCADE, flashcard_id UUID REFERENCES public.flashcards(id) ON DELETE SET NULL, answer TEXT, is_correct BOOLEAN NOT NULL);
ALTER TABLE public.flashcard_reviews ENABLE ROW LEVEL SECURITY; ALTER TABLE public.vocabulary_test_attempts ENABLE ROW LEVEL SECURITY; ALTER TABLE public.vocabulary_test_answers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own flashcard reviews" ON public.flashcard_reviews FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE POLICY "Own vocab attempts" ON public.vocabulary_test_attempts FOR ALL USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE POLICY "Own vocab answers" ON public.vocabulary_test_answers FOR ALL USING(EXISTS(SELECT 1 FROM public.vocabulary_test_attempts a WHERE a.id=attempt_id AND a.user_id=auth.uid()));
